var speed = 0.01;
var speedx = 5.00;
var speedy = 0.00;
var maxSize = 20;
var falloff = 200;
var steps = 13;
var highlightOnes = true;
var noiseValueAmplifier = 1.3;


function setup() {
	createCanvas(700, 400);

	textAlign(CENTER);

	noStroke();
}


function draw() {
	background(0);

	let noiseOffsetX = frameCount*speedx;
	let noiseOffsetY = frameCount*speedy;

	for (let x = 0; x < width; x+=(Math.max(0.001, Math.abs(steps)) || 1)) {
		for (let y = 0; y < height; y+=(Math.max(0.001, Math.abs(steps)) || 1)) {
			let mult = 0.1;

			let d = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), x, y);
			if (d < falloff) {
				mult = map(d, 0, falloff, 1, 0.1);
			}
			let n = noise((x+noiseOffsetX)*speed,(y+noiseOffsetY)*speed);
			let sw = n*maxSize*mult;

			let c1 = "0"; 
			let c2 = "1";

			if(highlightOnes){
				c1 = "1"; 
				c2 = "0"; 
			}

				textSize(sw*noiseValueAmplifier);
			if (n > 0.5) {
				fill(255);
				text(c1, x, y);
			}else {
				fill(200, 255, 200);
				text(c2, x, y);
			}
		}
	}
}

function mousePressed(){
	highlightOnes = !highlightOnes;
}
